/**
 * The MuVi Rehab mark: a rounded square in the primary colour holding a lens circle (vision)
 * crossed by a pulse line (EMG), with an accent glint. Drawn on a 32 × 32 grid.
 *
 * The LogoMark component and the favicon (generated by vite.config.ts) both draw from these
 * shapes, so they always match. No imports: vite.config.ts reads this file.
 */
export const LOGO_MARK = {
  viewBox: "0 0 32 32",
  background: "#0F5C5C",
  accent: "#D9682B",
  radius: 7,
  lens: { cx: 16, cy: 16, r: 8.5 },
  pulse: "M3.5 16h6.5l2.2-4.5 3.3 10 3.2-12 2.3 6.5h7.5",
  glint: { cx: 22.4, cy: 9.6, r: 1.9 },
  stroke: 2.2,
} as const;

/** The mark as a standalone SVG document, for the favicon. */
export function logoMarkSvg(): string {
  const m = LOGO_MARK;
  return [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${m.viewBox}">`,
    `<rect width="32" height="32" rx="${m.radius}" fill="${m.background}"/>`,
    `<circle cx="${m.lens.cx}" cy="${m.lens.cy}" r="${m.lens.r}" fill="none" stroke="#fff" stroke-width="${m.stroke}"/>`,
    `<path d="${m.pulse}" fill="none" stroke="#fff" stroke-width="${m.stroke}" stroke-linecap="round" stroke-linejoin="round"/>`,
    `<circle cx="${m.glint.cx}" cy="${m.glint.cy}" r="${m.glint.r}" fill="${m.accent}"/>`,
    `</svg>`,
  ].join("");
}
